int main(void) {
    int N, Q;
    if (scanf("%d %d", &N, &Q) != 2) return 0;

    long long *A = (long long *)malloc((size_t)N * sizeof(long long));
    if (!A) return 0;

    for (int i = 0; i < N; i++) scanf("%lld", &A[i]);

    for (int qi = 0; qi < Q; qi++) {
        int type, l, r;
        long long x, y;
        scanf("%d %d %d %lld %lld", &type, &l, &r, &x, &y);

        /* assuming 1-based indices in input */
        l--;
        r--;

        if (l < 0) l = 0;
        if (r >= N) r = N - 1;

        if (type == 1) {
            /* add x, then multiply by y */
            for (int i = l; i <= r; i++) {
                A[i] = (A[i] + x) * y;
            }
        } else {
            /* subtract x, then divide by y if y != 0 */
            for (int i = l; i <= r; i++) {
                A[i] = A[i] - x;
                if (y != 0) A[i] /= y;
            }
        }
    }

    long long L, R;
    scanf("%lld %lld", &L, &R);

    int count = 0;
    for (int i = 0; i < N; i++) {
        if (A[i] >= L && A[i] <= R) count++;
    }

    printf("%d\n", count);

    free(A);
    return 0;
}

