public class Solution {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        // Read N and Q
        st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int Q = Integer.parseInt(st.nextToken());

        // Read initial array
        long[] arr = new long[N];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            arr[i] = Long.parseLong(st.nextToken());
        }

        // Process queries
        for (int q = 0; q < Q; q++) {
            st = new StringTokenizer(br.readLine());
            int type = Integer.parseInt(st.nextToken());

            if (type == 1) {
                // Add and multiply: add value to elements, then multiply
                int l = Integer.parseInt(st.nextToken());
                int r = Integer.parseInt(st.nextToken());
                long addVal = Long.parseLong(st.nextToken());
                long mulVal = Long.parseLong(st.nextToken());

                for (int i = l; i <= r; i++) {
                    arr[i] = (arr[i] + addVal) * mulVal;
                }
            } else {
                // Subtract and divide: subtract value from elements, then divide
                int l = Integer.parseInt(st.nextToken());
                int r = Integer.parseInt(st.nextToken());
                long subVal = Long.parseLong(st.nextToken());
                long divVal = Long.parseLong(st.nextToken());

                for (int i = l; i <= r; i++) {
                    arr[i] = (arr[i] - subVal) / divVal;
                }
            }
        }

        // Read L and R
        st = new StringTokenizer(br.readLine());
        long L = Long.parseLong(st.nextToken());
        long R = Long.parseLong(st.nextToken());

        // Count elements in range [L, R]
        int count = 0;
        for (int i = 0; i < N; i++) {
            if (arr[i] >= L && arr[i] <= R) {
                count++;
            }
        }

        System.out.println(count);
    }
}

